import{z as o,x as n,o as A,c as d,q as l,j as r,D as e,d as t,s as i,S as B,b as E}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"CPI 与阿姆达尔","description":"","frontmatter":{"title":"CPI 与阿姆达尔","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cpi-amdahl.md","filePath":"cs/cpi-amdahl.md","lastUpdated":1791413859000}'),p={name:"cs/cpi-amdahl.md"};function C(m,a,P,h,c,f){const s=n("Mermaid");return A(),d("div",null,[a[2]||(a[2]=l('<h1 id="cpi-与阿姆达尔" tabindex="-1">CPI 与阿姆达尔 <a class="header-anchor" href="#cpi-与阿姆达尔" aria-label="Permalink to &quot;CPI 与阿姆达尔&quot;">​</a></h1><div class="epigraph"><p>加速比被未改进部分卡住；把流水线的理想 CPI 写成 1，真正的时间仍在停顿和那一小段加速不了的工作里。</p><footer>—— 据 Amdahl, Validity of the single processor approach to achieving large scale computing capabilities, AFIPS 1967 整理</footer></div><p><a href="/cs/delay-slot">上一课</a>把精确异常钉在提交点上，冲刷会丢掉已经取进来的指令。五级、转发、预测、异常路径至此都有了对象。本课不重讲任何一种冒险怎么修。缺口是：还没有把「每条指令多少拍」和「改进一块能快多少」写成可加减的量。本课只交出 CPI 分解和阿姆达尔定律。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>理想五级的 CPI 是 1。结构气泡、load-use、误预测冲刷、陷阱入口都把平均 CPI 抬高。只说「流水线更快」无法比较两种设计：时钟可能更高，但停顿也可能更多。缺口不是再发明一级流水线，而是<strong>CPU 时间 = 指令数 × CPI × 时钟周期</strong>，并把 CPI 拆成基础 1 加上各类停顿。</p><p>Amdahl 进一步问：若只有比例 \\(f\\) 的时间被加速 \\(s\\) 倍，整体加速比是 \\(1/((1-f)+f/s)\\)。把全部面积砸在已经很短的那一段上，收益趋零。本课不把定律用到多核负载均衡的故事；多核是后课。</p><p><span class="marginnote">Amdahl 1967 的原文针对「单处理器思路能否靠加速一部分达到大规模」；教学上用来约束任何局部优化。</span></p><p><span class="marginnote">数字实例：假设每 5 条指令遇到 1 次分支，每次误预测浪费 3 拍，则停顿项 = 0.2 × 3 = 0.6，CPI = 1 + 0.6 = 1.6——比理想流水线慢 60%。只改时钟频率而不降停顿，这 0.6 会原样跟着放大。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记 \\(\\mathrm{CPI} = \\mathrm{CPI}_\\text{ideal} + \\sum_i \\text{停顿}_i\\)。五级理想项取 1；停顿按结构、数据、控制、异常分别计数，再按指令频率加权。CPU 时间用这条乘时钟。比较设计时，同时看时钟能否缩短——转发 mux 可能让周期变长，净效果不一定赢。</p>',10)),(A(),r(B,null,{default:e(()=>[i(s,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20INST%5B%22%E6%8C%87%E4%BB%A4%E6%95%B0%22%5D%20--%3E%20T%5B%22CPU%20%E6%97%B6%E9%97%B4%22%5D%0A%20%20CPI%5B%22CPI%20%3D%201%20%2B%20%E5%81%9C%E9%A1%BF%22%5D%20--%3E%20T%0A%20%20CLK%5B%22%E6%97%B6%E9%92%9F%E5%91%A8%E6%9C%9F%22%5D%20--%3E%20T%0A%20%20T%20--%3E%20A%5B%22%E9%98%BF%E5%A7%86%E8%BE%BE%E5%B0%94%EF%BC%9A%E6%9C%AA%E5%8A%A0%E9%80%9F%E9%83%A8%E5%88%86%E5%B0%81%E9%A1%B6%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"加速比 \\(S = T_\\text{old}/T_\\text{new}\\)。若只改进分支预测，把 \\(f\\) 取成原先花在误预测冲刷上的时间比例，\\(s\\) 取成该项的局部加速，整体 \\(S\\) 立刻小于 \\(s\\)。",-1)),a[4]||(a[4]=E("p",null,[E("span",{class:"marginnote"},"数字实例：\\(f = 0.9\\)、\\(s = 10\\) 时，\\(S = 1/(0.1 + 0.09) \\approx 5.3\\)；就算把 \\(s\\) 换成无穷大，\\(S\\) 也只有 10——那没被加速的 10% 就是天花板。初学者容易把 \\(f\\) 当成代码行数占比，实际它是按运行时间加权的：一个跑 90% 时间的循环，行数可能不到 1%。")],-1)),a[5]||(a[5]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=E("p",null,"定量以后，后课 cache 缺失、TLB 失效都可以加进同一条 CPI 公式，而不必改 ISA。局部性课要解释为什么存储器停顿会主导这项；本课只把公式的位置留好。",-1)),a[7]||(a[7]=E("p",null,"阿姆达尔也解释为什么要把常见路径做快：指令频率高的那类停顿，值得加硬件；罕见陷阱路径可以慢。这与特权级里「陷阱罕见」一致，不引入新的保护模型。",-1)),(A(),r(B,null,{default:e(()=>[i(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20NEW%5B%22%E5%87%BA%E7%8E%B0%E6%96%B0%E7%9A%84%E5%81%9C%E9%A1%BF%E6%BA%90%2C%20%E5%A6%82%20cache%20%E7%BC%BA%E5%A4%B1%22%5D%20--%3E%20MEA%5B%22%E6%B5%8B%E9%87%8F%3A%20%E6%AF%8F%E6%9D%A1%E6%8C%87%E4%BB%A4%E5%8F%91%E7%94%9F%E5%87%A0%E6%AC%A1%22%5D%0A%20%20MEA%20--%3E%20PEN%5B%22%E6%8A%98%E7%AE%97%3A%20%E6%AC%A1%E6%95%B0%20%C3%97%20%E6%AF%8F%E6%AC%A1%E6%B5%AA%E8%B4%B9%E6%8B%8D%E6%95%B0%22%5D%0A%20%20PEN%20--%3E%20ADD%5B%22%E5%8A%A0%E8%BF%9B%20CPI%20%E7%9A%84%E5%81%9C%E9%A1%BF%E9%A1%B9%22%5D%0A%20%20ADD%20--%3E%20T%5B%22CPU%20%E6%97%B6%E9%97%B4%E9%9A%8F%E4%B9%8B%E6%8A%AC%E9%AB%98%22%5D%0A%20%20T%20--%3E%20EVAL%5B%22%E6%94%B9%E8%BF%99%E5%9D%97%3A%20%E7%94%A8%E9%98%BF%E5%A7%86%E8%BE%BE%E5%B0%94%E7%AE%97%E6%95%B4%E4%BD%93%E5%8A%A0%E9%80%9F%E6%AF%94%22%5D%0A%20%20EVAL%20--%3E%7C%22%E5%8D%A0%E6%AF%94%E5%B0%8F%22%7C%20SKIP%5B%22%E4%B8%8D%E5%80%BC%E5%BE%97%E5%8A%A0%E7%A1%AC%E4%BB%B6%22%5D%0A%20%20EVAL%20--%3E%7C%22%E5%8D%A0%E6%AF%94%E5%A4%A7%22%7C%20DO%5B%22%E5%80%BC%E5%BE%97%E5%8A%A0%E7%A1%AC%E4%BB%B6%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=l('<p><span class="marginnote">这张图回答的是框架的复用问题：后课的 cache、TLB 都不是另起公式，而是往停顿项里再加一项。第一张图讲 CPU 时间由什么构成，这张讲新机制怎么「登记入户」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 IPC 大于 1：那是<a href="/cs/superscalar-issue">超标量发射</a>把理想项改成小于 1 的写法。也不把定律误写成「永远只能加速 20%」——\\(f\\) 来自测量，不是常数。Gustafson 的按比例放大是另一种问题，主干不在这里展开。</p><p>后课默认：谈到性能，先写指令数、CPI、周期三项；cache 与 VM 的缺失延迟加在 CPI 的停顿项里。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CPU 时间 = 指令数 × CPI × 周期；五级理想 CPI 为 1，停顿另加。</li><li>阿姆达尔：整体加速被未改进比例封顶。</li><li>存储器层次与超标量会改写 CPI 的项，对象仍是这条公式。</li><li>出处：Amdahl, AFIPS 1967；Hennessy and Patterson, <em>CA:AQA</em> 第 1 章。</li></ul>',6))])}const I=o(p,[["render",C]]);export{D as __pageData,I as default};
